  t: (k: CopyKey, v?: Record<string, string | number>) => string
) {
  return result.province_count > 1
    ? t("pickArea", {
        pc: result.postal_code,
        n: result.areas.length,
        p: result.province_count,
      })
    : t("pickAreaOneProvince", {
        pc: result.postal_code,
        n: result.areas.length,
        d: result.district_count,
      })
