}

/**
 * The single search box: an ARIA 1.2 combobox (input + listbox) over every
 * subdistrict, matching Thai and English and ignoring ต./อ./จ./เขต/แขวง.
 * Results come ranked from the core's search, so nothing is filtered here.
 * The list sits under the input, so it works the same on a phone.
 */
export function AddressSearch({
  id,
  client,
  locale,
  t,
  showFacilityCodes,
  disabled,
  onPick,
  onFillManually,
}: AddressSearchProps) {
  const [query, setQuery] = React.useState("")
  const [result, setResult] = React.useState<SearchResult | null>(null)
  const [loading, setLoading] = React.useState(false)
  const [open, setOpen] = React.useState(false)
  const [activeIndex, setActiveIndex] = React.useState(-1)
  const seq = React.useRef(0)

  React.useEffect(() => {
    const n = ++seq.current
    if (!query.trim()) return
    // eslint-disable-next-line react-hooks/set-state-in-effect -- marks the search this effect starts
    setLoading(true)
    client
      .search(query, { includeFacility: showFacilityCodes })
      .then((r) => {
        if (n !== seq.current) return
        setResult(r)
        setActiveIndex(-1)
      })
      .catch(() => n === seq.current && setResult(null))
      .finally(() => n === seq.current && setLoading(false))
  }, [query, client, showFacilityCodes])

  // An emptied box shows no results, whatever the last search returned.
  const current = query.trim() ? result : null
  const hits = current?.status === "ok" ? current.hits : []
  const empty = current?.status === "ok" && hits.length === 0 && !loading
  const expanded = open && hits.length > 0
  const listId = `${id}-list`
  const descId = `${id}-desc`
  const optionId = (i: number) => `${id}-option-${i}`

  const choose = (hit: SearchHit) => {
    const line = lineText(hit, locale)
    onPick(hit, line)
    setQuery(line)
    setOpen(false)
    setActiveIndex(-1)
  }

  const onKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "ArrowDown") {
      e.preventDefault()
      setOpen(true)
      if (hits.length) setActiveIndex((i) => (i + 1) % hits.length)
    } else if (e.key === "ArrowUp") {
      e.preventDefault()
      setOpen(true)
      if (hits.length) setActiveIndex((i) => (i <= 0 ? hits.length - 1 : i - 1))
    } else if (e.key === "Enter" && expanded) {
      // Never submit the form from an open list: Enter with nothing
      // highlighted highlights the first result, and a second Enter picks it.
      e.preventDefault()
      if (activeIndex >= 0) choose(hits[activeIndex]!)
      else setActiveIndex(0)
    } else if (e.key === "Escape" && expanded) {
      e.preventDefault()
      setOpen(false)
      setActiveIndex(-1)
    }
  }

  return (
    <Field>
      <FieldLabel htmlFor={id}>{t("search")}</FieldLabel>
      <div className="relative">
        <SearchIcon
          aria-hidden
          className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground"
        />
        <Input
          id={id}
          type="text"
          role="combobox"
          autoComplete="off"
          spellCheck={false}
          aria-autocomplete="list"
          aria-expanded={expanded}
          aria-controls={listId}
          aria-activedescendant={
            expanded && activeIndex >= 0 ? optionId(activeIndex) : undefined
          }
          aria-describedby={descId}
          placeholder={t("searchPh")}
          value={query}
          disabled={disabled}
          className="pr-8 pl-8"
          onChange={(e) => {
            setQuery(e.target.value)
            setOpen(true)
          }}
          onFocus={() => {
            setOpen(true)
            client.preload("search").catch(() => {
              // The search itself reports the failure.
            })
          }}
          onBlur={() => setOpen(false)}
          onKeyDown={onKeyDown}
        />
        {loading && query.trim() ? (
          <Loader2Icon
            aria-hidden
            className="absolute top-1/2 right-2.5 size-4 -translate-y-1/2 animate-spin text-muted-foreground motion-reduce:animate-none"
          />
        ) : null}
        <div
          className={cn(
            "z-50 mt-1 w-full rounded-lg bg-popover p-1 text-sm text-popover-foreground shadow-md ring-1 ring-foreground/10 sm:absolute",
            !expanded && "hidden"
          )}
        >
          <ul
            id={listId}
            role="listbox"
            aria-label={t("search")}
            className="flex flex-col"
          >
            {hits.map((h, i) => (
              <li
                key={hitKey(h)}
                id={optionId(i)}
                role="option"
                aria-selected={i === activeIndex}
                data-selected={i === activeIndex || undefined}
                // Keep focus in the input; choose on mouse down before blur closes the list.
                onMouseDown={(e) => {
                  e.preventDefault()
                  choose(h)
                }}
                onMouseMove={() => setActiveIndex(i)}
                className="flex min-h-11 cursor-default items-start justify-between gap-3 rounded-sm px-2 py-1.5 select-none sm:min-h-0 data-selected:bg-muted"
              >
                <span className="min-w-0">
                  <HitLine hit={h} locale={locale} />
                </span>
                {h.level === "subdistrict" && h.postal_code ? (
                  <span className="shrink-0 text-muted-foreground tabular-nums">
                    {h.postal_code}
                  </span>
                ) : null}
              </li>
            ))}
          </ul>
          {current?.status === "ok" && current.more ? (
            <p className="px-2 py-1.5 text-xs text-muted-foreground">
              {t("searchMore")}
            </p>
          ) : null}
        </div>
      </div>
      <FieldDescription id={descId}>{t("searchDesc")}</FieldDescription>
      {empty ? (
        <div className="flex flex-col items-start gap-1 rounded-lg border border-dashed p-3 text-sm">
          <p className="font-medium">{t("searchEmpty", { s: query.trim() })}</p>
          <p className="text-muted-foreground">{t("searchEmptyBody")}</p>
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="mt-1"
            onClick={onFillManually}
          >
            {t("fillManually")}
          </Button>
        </div>
      ) : null}
      <span className="sr-only" aria-live="polite">
        {current?.status === "ok" && open
          ? t("liveResults", { n: hits.length })
          : ""}
      </span>
    </Field>
  )
}

const hitKey = (h: SearchHit) =>
  h.level === "subdistrict"
    ? `${h.subdistrict.code}-${h.postal_code}`
    : h.level === "district"
      ? h.district.code
      : h.province.code

function lineText(hit: SearchHit, locale: Locale): string {
  return parts(hit, locale)
    .map((p) => p.prefix + p.name + p.suffix)
    .join("")
}

type Part = {
  level: "subdistrict" | "district" | "province"
  prefix: string
  name: string
  suffix: string
  range: [number, number] | undefined
}

/**
 * The one-line address as prefix + name pieces, so the matched part of each
 * name can be bold. A district or province hit has only its own levels.
 */
function parts(hit: SearchHit, locale: Locale): Part[] {
  const r = hit.match.ranges
  // A match in the other language bolds the whole name: "karon" bolds กะรน.
  const pick = (
    n: { th: string; en: string | null },
    ranges: NameRanges | undefined
  ) => {
    const name = locale === "en" ? (n.en ?? n.th) : n.th
    const own = locale === "en" && n.en ? ranges?.en : ranges?.th
    const range: [number, number] | undefined =
      own ?? (ranges?.th || ranges?.en ? [0, name.length] : undefined)
    return { name, range }
  }
  const bangkok = hit.province.kind === "special_administrative_area"
  const out: Omit<Part, "suffix">[] = []
  if (hit.level === "subdistrict") {
    out.push({
      level: "subdistrict",
      prefix:
        locale === "en"
          ? ""
          : hit.subdistrict.kind === "khwaeng" || bangkok
            ? "แขวง"
            : "ตำบล",
      ...pick(hit.subdistrict.name, r.subdistrict),
    })
  }
  if (hit.level !== "province") {
    out.push({
      level: "district",
      prefix:
        locale === "en"
          ? ""
          : hit.district.kind === "khet" || bangkok
            ? "เขต"
            : "อำเภอ",
      ...pick(hit.district.name, r.district),
    })
  }
  out.push({
    level: "province",
    prefix: locale === "en" || bangkok ? "" : "จังหวัด",
    ...pick(hit.province.name, r.province),
  })
  const sep = locale === "en" ? ", " : " "
  return out.map((p, i) => ({ ...p, suffix: i < out.length - 1 ? sep : "" }))
}

function HitLine({ hit, locale }: { hit: SearchHit; locale: Locale }) {
  return (
    <>
      {parts(hit, locale).map((p) => (
        <React.Fragment key={p.level}>
          {p.prefix}
          {p.range ? (
            <>
              {p.name.slice(0, p.range[0])}
              <strong className="font-semibold">
                {p.name.slice(p.range[0], p.range[1])}
              </strong>
              {p.name.slice(p.range[1])}
            </>
          ) : (
            p.name
          )}
          {p.suffix}
        </React.Fragment>
      ))}
    </>
  )
}

"use client"

import * as React from "react"
import { CheckIcon, ChevronsUpDownIcon, Loader2Icon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command"
import {
  Drawer,
  DrawerContent,
  DrawerDescription,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "@/components/ui/drawer"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"

import { useMediaQuery } from "./use-media-query"

export type PickerOption = {
  value: string
  label: string
  /** A second line, e.g. "อ.บ้านแพรก › พระนครศรีอยุธยา". */
  description?: string
  /** Extra text the list's own search matches, e.g. the English name. */
  keywords?: string[]
}

type AddressPickerProps = {
  id: string
  label: string
  options: PickerOption[]
  value: string | null
  onValueChange: (value: string) => void
  placeholder: string
  searchPlaceholder: string
  emptyText: string
  /** Shown as a heading over the list, e.g. "10200 · เขตพระนคร". */
  groupHeading?: string
  disabled?: boolean
  invalid?: boolean
  loading?: boolean
  describedBy?: string
  onOpen?: () => void
}

/**
 * A select with a search field: Popover + Command on desktop, a bottom Drawer
 * below 640px (shadcn's responsive combobox). The trigger is the labelled
 * control, so <Label htmlFor={id}> names it.
 */
export function AddressPicker({
  id,
  label,
  options,
  value,
  onValueChange,
  placeholder,
  searchPlaceholder,
  emptyText,
  groupHeading,
  disabled,
  invalid,
  loading,
  describedBy,
  onOpen,
}: AddressPickerProps) {
  const [open, setOpen] = React.useState(false)
  const desktop = useMediaQuery("(min-width: 640px)")
  const listId = `${id}-list`
  const selected = options.find((o) => o.value === value)

  const setOpenAndNotify = (next: boolean) => {
    setOpen(next)
    if (next) onOpen?.()
  }

  const select = (v: string) => {
    onValueChange(v)
    setOpen(false)
  }

  const trigger = (
    <Button
      id={id}
      type="button"
      variant="outline"
      role="combobox"
      aria-expanded={open}
      aria-controls={open ? listId : undefined}
      aria-haspopup="listbox"
      aria-invalid={invalid || undefined}
      aria-describedby={describedBy}
      disabled={disabled}
      className={cn(
        "w-full justify-between font-normal",
        !selected && "text-muted-foreground"
      )}
    >
      <span className="truncate">
        {selected ? selected.label : placeholder}
      </span>
      {loading ? (
        <Loader2Icon
          aria-hidden
          className="size-4 shrink-0 animate-spin motion-reduce:animate-none"
        />
      ) : (
        <ChevronsUpDownIcon
          aria-hidden
          className="size-4 shrink-0 opacity-50"
        />
      )}
    </Button>
  )

  const list = (
    <Command
      filter={(itemValue, search, keywords) => {
        const q = search.toLowerCase().replace(/\s+/g, "")
        const hay = [itemValue, ...(keywords ?? [])]
          .join(" ")
          .toLowerCase()
          .replace(/\s+/g, "")
        return hay.includes(q) ? 1 : 0
      }}
    >
      <CommandInput
        placeholder={searchPlaceholder}
        aria-label={searchPlaceholder}
      />
      <CommandList
        id={listId}
        aria-label={label}
        className={cn(!desktop && "max-h-[60vh]")}
      >
        <CommandEmpty>{emptyText}</CommandEmpty>
        <CommandGroup heading={groupHeading}>
          {options.map((o) => (
            <CommandItem
              key={o.value}
              value={`${o.label} ${o.value}`}
              keywords={o.keywords ?? []}
              onSelect={() => select(o.value)}
              className={cn(!desktop && "min-h-11")}
            >
              <span className="flex min-w-0 flex-col">
                <span className="truncate">{o.label}</span>
                {o.description ? (
                  <span className="truncate text-xs text-muted-foreground">
                    {o.description}
                  </span>
                ) : null}
              </span>
              <CheckIcon
                aria-hidden
                className={cn(
                  "ml-auto size-4",
                  o.value === value ? "opacity-100" : "opacity-0"
                )}
              />
            </CommandItem>
          ))}
        </CommandGroup>
      </CommandList>
    </Command>
  )

  if (desktop) {
    return (
      <Popover open={open} onOpenChange={setOpenAndNotify}>
        <PopoverTrigger asChild>{trigger}</PopoverTrigger>
        <PopoverContent
          className="w-(--radix-popover-trigger-width) min-w-56 p-0"
          align="start"
        >
          {list}
        </PopoverContent>
      </Popover>
    )
  }

  return (
    <Drawer open={open} onOpenChange={setOpenAndNotify}>
      <DrawerTrigger asChild>{trigger}</DrawerTrigger>
      <DrawerContent>
        <DrawerHeader className="text-left">
          <DrawerTitle>{label}</DrawerTitle>
          <DrawerDescription className="sr-only">
            {searchPlaceholder}
          </DrawerDescription>
        </DrawerHeader>
        <div className="px-2 pb-4">{list}</div>
      </DrawerContent>
    </Drawer>
  )
}

import type {
  Area,
  District,
  LocalizedName,
  Province,
  Subdistrict,
} from "@farzai/thailand-address"

import type { CopyKey, Locale, Translate } from "./address-form-copy"

export const nameIn = (n: LocalizedName, locale: Locale) =>
  locale === "en" ? (n.en ?? n.th) : n.th

/** The Bangkok kinds (khet, khwaeng) or the provincial ones; null when no province is known yet. */
export function levelKinds(
  province: Pick<Province, "kind"> | null | undefined,
  district?: Pick<District, "kind"> | null,
  subdistrict?: Pick<Subdistrict, "kind"> | null
): { district: CopyKey; subdistrict: CopyKey } {
  if (!province) return { district: "district", subdistrict: "subdistrict" }
  const bangkok = province.kind === "special_administrative_area"
  const d: CopyKey =
    district?.kind ??
    (province.kind === null ? "district" : bangkok ? "khet" : "amphoe")
  const s: CopyKey =
    subdistrict?.kind ??
    (province.kind === null ? "subdistrict" : bangkok ? "khwaeng" : "tambon")
  return { district: d, subdistrict: s }
}

/** "อ.บ้านแพรก › พระนครศรีอยุธยา" / "Ban Phraek › Phra Nakhon Si Ayutthaya", the second line of an area choice. */
export function areaContext(a: Area, locale: Locale): string {
  if (locale === "en")
    return `${nameIn(a.district.name, "en")} › ${nameIn(a.province.name, "en")}`
  const prefix = a.district.kind === "khet" ? "เขต" : "อ."
  return `${prefix}${a.district.name.th} › ${a.province.name.th}`
}

/** "อำเภอ ตำบล และรหัสไปรษณีย์" / "District, subdistrict and postal code". */
export function joinList(items: string[], locale: Locale): string {
  if (items.length <= 1) return items.join("")
  const last = items[items.length - 1]
  const head = items.slice(0, -1)
  if (locale === "en") {
    const s = `${head.join(", ")} and ${last}`
    return s.charAt(0).toUpperCase() + s.slice(1).toLowerCase()
  }
  return `${head.join(" ")} และ${last}`
}

export const sortByName = <T extends { name: LocalizedName }>(
  items: T[],
  locale: Locale
): T[] => {
  const collator = new Intl.Collator(locale)
  return [...items].sort((a, b) =>
    collator.compare(nameIn(a.name, locale), nameIn(b.name, locale))
  )
}

export type { Translate }

import * as React from "react"

/** Whether a media query matches, kept in sync with the viewport. */
export function useMediaQuery(query: string): boolean {
  const subscribe = React.useCallback(
    (onChange: () => void) => {
      const mql = window.matchMedia(query)
      mql.addEventListener("change", onChange)
      return () => mql.removeEventListener("change", onChange)
    },
    [query]
  )
  return React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => true
  )
}
